diem = {"An": 8, "Binh": 6, "Cuong": 9}
with open("diem.txt", "w", encoding="utf-8") as f:
    for ten, d in diem.items():
        f.write(ten + " " + str(d) + "\n")

with open("diem.txt", "r", encoding="utf-8") as f:
    for dong in f:
        ten, d = dong.split()
        print(ten, "->", d)
